    -- 0 when changes are applied to the server.
    --
    SELECT [dbo].[tblTransactionLineItems].[SequenceID],[dbo].[tblTransactionLineItems].[MeterStart],[dbo].[tblTransactionLineItems].[MeterStop],[dbo].[tblTransactionLineItems].[GrossQuantity],[dbo].[tblTransactionLineItems].[DeliveredGrossQuantity],[dbo].[tblTransactionLineItems].[Temperature],[dbo].[tblTransactionLineItems].[Vcf],[dbo].[tblTransactionLineItems].[Density],[dbo].[tblTransactionLineItems].[Product],[dbo].[tblTransactionLineItems].[ProductCode],[dbo].[tblTransactionLineItems].[ProductType],[dbo].[tblTransactionLineItems].[ProductPrice],[dbo].[tblTransactionLineItems].[CLIN],[dbo].[tblTransactionLineItems].[NetQuantity],[dbo].[tblTransactionLineItems].[DeliveredNetQuantity],[dbo].[tblTransactionLineItems].[Pressure],[dbo].[tblTransactionLineItems].[ContractNumber],[dbo].[tblTransactionLineItems].[DestinationRegistrationID],[dbo].[tblTransactionLineItems].[DestinationSerialNumber],[dbo].[tblTransactionLineItems].[DestinationEquipmentType],[dbo].[tblTransactionLineItems].[DestinationEquipmentModel],[dbo].[tblTransactionLineItems].[DestinationCompanyEquipmentID],[dbo].[tblTransactionLineItems].[DestinationCompartmentID],[dbo].[tblTransactionLineItems].[SourceRegistrationID],[dbo].[tblTransactionLineItems].[SourceSerialNumber],[dbo].[tblTransactionLineItems].[SourceEquipmentType],[dbo].[tblTransactionLineItems].[SourceEquipmentModel],[dbo].[tblTransactionLineItems].[SourceCompanyEquipmentID],[dbo].[tblTransactionLineItems].[SourceCompartmentID],[dbo].[tblTransactionLineItems].[MeterFactor],[dbo].[tblTransactionLineItems].[LineItemSequenceNumber],[dbo].[tblTransactionLineItems].[BatchNumber],[dbo].[tblTransactionLineItems].[DocumentNumber],[dbo].[tblTransactionLineItems].[LineFill],[dbo].[tblTransactionLineItems].[BottomVolume],[dbo].[tblTransactionLineItems].[NetCapacity],[dbo].[tblTransactionLineItems].[Customs],[dbo].[tblTransactionLineItems].[ArmNumber],[dbo].[tblTransactionLineItems].[LineNumber],[dbo].[tblTransactionLineItems].[OperatorID],[dbo].[tblTransactionLineItems].[TankStatus],[dbo].[tblTransactionLineItems].[MeterStartDateTime],[dbo].[tblTransactionLineItems].[MeterStopDateTime],[dbo].[tblTransactionLineItems].[Pit],[dbo].[tblTransactionLineItems].[RequestedDateTime],[dbo].[tblTransactionLineItems].[DispatchedDateTime],[dbo].[tblTransactionLineItems].[AcknowledgedDateTime],[dbo].[tblTransactionLineItems].[OnLocationTime],[dbo].[tblTransactionLineItems].[ValidationDateTime],[dbo].[tblTransactionLineItems].[CompletionDateTime],[dbo].[tblTransactionLineItems].[ReceiptVariance],[dbo].[tblTransactionLineItems].[DifferentialPressure],[dbo].[tblTransactionLineItems].[LoadRackVariance],[dbo].[tblTransactionLineItems].[RequestedBy],[dbo].[tblTransactionLineItems].[FreezePoint],[dbo].[tblTransactionLineItems].[DeleteFlag],[dbo].[tblTransactionLineItems].[StorageLocationID],[dbo].[tblTransactionLineItems].[MeterID],[dbo].[tblTransactionLineItems].[AdditiveProfileID],[dbo].[tblTransactionLineItems].[CreatedBy],[dbo].[tblTransactionLineItems].[CreatedDate],[dbo].[tblTransactionLineItems].[UpdatedBy],[dbo].[tblTransactionLineItems].[UpdatedDate],[dbo].[tblTransactionLineItems].[PresetAmount],[dbo].[tblTransactionLineItems].[EngineeringUnitsIndex],[dbo].[tblTransactionLineItems].[CustomerProductName],[dbo].[tblTransactionLineItems].[CustomerProductCode],CONVERT(CHAR(10), [dbo].[tblTransactionLineItems].[TransactionInventoryDate], 111) AS [TransactionInventoryDate],[dbo].[tblTransactionLineItems].[COAWaiver],[dbo].[tblTransactionLineItems].[COANote],[dbo].[tblTransactionLineItems].[COAID],[dbo].[tblTransactionLineItems].[Tax1],[dbo].[tblTransactionLineItems].[Tax2],[dbo].[tblTransactionLineItems].[Tax3],[dbo].[tblTransactionLineItems].[Tax4],[dbo].[tblTransactionLineItems].[Tax5],[dbo].[tblTransactionLineItems].[TransVersion],[dbo].[tblTransactionLineItems].[LoadingLocationID],[dbo].[tblTransactionLineItems].[ImproperAdditization],[dbo].[tblTransactionLineItems].[BrokenBlend],[dbo].[tblTransactionLineItems].[ContaminatePrompt],[dbo].[tblTransactionLineItems].[CompartmentsPreviouslyLoaded],[dbo].[tblTransactionLineItems].[CompartmentsEmpty],[dbo].[tblTransactionLineItems].[Flag01],[dbo].[tblTransactionLineItems].[Flag02],[dbo].[tblTransactionLineItems].[Flag03],[dbo].[tblTransactionLineItems].[Flag04],[dbo].[tblTransactionLineItems].[Flag05],[dbo].[tblTransactionLineItems].[Flag06],[dbo].[tblTransactionLineItems].[Number01],[dbo].[tblTransactionLineItems].[Number02],[dbo].[tblTransactionLineItems].[Number03],[dbo].[tblTransactionLineItems].[Number04],[dbo].[tblTransactionLineItems].[Number05],[dbo].[tblTransactionLineItems].[Number06],[dbo].[tblTransactionLineItems].[OdometerHours],[dbo].[tblTransactionLineItems].[EndDeliveryDate],[dbo].[tblTransactionLineItems].[RequestedDeliveryDate],[dbo].[tblTransactionLineItems].[InvoiceNumber],[dbo].[tblTransactionLineItems].[InvoiceLineNumber],[dbo].[tblTransactionLineItems].[AlternativeGrossVolume],[dbo].[tblTransactionLineItems].[AlternativeNetVolume],[dbo].[tblTransactionLineItems].[AlternativeUnits],[dbo].[tblTransactionLineItems].[TankLevel],[dbo].[tblTransactionLineItems].[TankLevelUnits],[dbo].[tblTransactionLineItems].[Date01],[dbo].[tblTransactionLineItems].[Date02],[dbo].[tblTransactionLineItems].[Date03],[dbo].[tblTransactionLineItems].[Date04],[dbo].[tblTransactionLineItems].[NonDomesticPrice],[dbo].[tblTransactionLineItems].[CurrencyUnit],[dbo].[tblTransactionLineItems].[ExchangeRate],[dbo].[tblTransactionLineItems].[QualityTestNumber],[dbo].[tblTransactionLineItems].[Odometer],[dbo].[tblTransactionLineItems].[DeliveryLocation],[dbo].[tblTransactionLineItems].[Variance],[dbo].[tblTransactionLineItems].[PartialFill],[dbo].[tblTransactionLineItems].[MassQuantity],[dbo].[tblTransactionLineItems].[NetManualValueFlag],[dbo].[tblTransactionLineItems].[MassManualValueFlag],[dbo].[tblTransactionLineItems].[GrossManualValueFlag],[dbo].[tblTransactionLineItems].[VcfManualValueFlag],[dbo].[tblTransactionLineItems].[DeliveredGrossManualValu